/* AUTO-GENERATED trace frames (sparse, ~1/s, 640px JPEG).
   For TRACE_MODE alignment only. Keyed by master ms. */
export const TRACE_FRAMES: { ms: number; src: string }[] = [
  { ms: 0, src: "data:image/jpeg;base64," },
  { ms: 1000, src: "data:image/jpeg;base64," },
  { ms: 2000, src: "data:image/jpeg;base64," },
  { ms: 3000, src: "data:image/jpeg;base64," },
  { ms: 4000, src: "data:image/jpeg;base64," },
  { ms: 5000, src: "data:image/jpeg;base64," },
  { ms: 6000, src: "data:image/jpeg;base64," },
  { ms: 7000, src: "data:image/jpeg;base64," },
  { ms: 8000, src: "data:image/jpeg;base64," },
  { ms: 9000, src: "data:image/jpeg;base64," },
  { ms: 10000, src: "data:image/jpeg;base64," },
  { ms: 11000, src: "data:image/jpeg;base64," },
  { ms: 12000, src: "data:image/jpeg;base64," },
  { ms: 13000, src: "data:image/jpeg;base64," },
  { ms: 14000, src: "data:image/jpeg;base64," },
  { ms: 15000, src: "data:image/jpeg;base64," },
  { ms: 16000, src: "data:image/jpeg;base64," },
  { ms: 17000, src: "data:image/jpeg;base64," },
  { ms: 18000, src: "data:image/jpeg;base64," },
  { ms: 19000, src: "data:image/jpeg;base64," },
  { ms: 20000, src: "data:image/jpeg;base64," },
  { ms: 21000, src: "data:image/jpeg;base64," },
  { ms: 22000, src: "data:image/jpeg;base64," },
  { ms: 23000, src: "data:image/jpeg;base64," },
  { ms: 24000, src: "data:image/jpeg;base64," },
];

export function traceFrameFor(ms: number): string | null {
  if (!TRACE_FRAMES.length) return null;
  let best = TRACE_FRAMES[0];
  for (const f of TRACE_FRAMES) {
    if (Math.abs(f.ms - ms) < Math.abs(best.ms - ms)) best = f;
  }
  return best.src;
}
